function spawnEnemies(){let count=Math.min(10,4+Math.ceil(floor*.6));let points=shuffled([[.22,.24],[.78,.24],[.22,.76],[.78,.76],[.5,.2],[.5,.8],[.18,.5],[.82,.5],[.36,.3],[.64,.7]]);enemies=points.slice(0,count).map((p,i)=>({id:i+1,x:W*p[0],y:H*p[1],r:17,hp:(4+floor*1.4)*(coopActive?1.35:1),initialHP:(4+floor*1.4)*(coopActive?1.35:1),type:i%3,champion:floor>=2&&Math.random()<Math.min(.45,.12+floor*.025),age:Math.random()*3,fire:1+Math.random()*.6,burn:0,dash:0,dx:0,dy:0}));for(let e of enemies)if(e.champion)e.hp=Math.ceil(e.hp*1.65);for(let e of enemies)e.initialHP=e.hp;for(let e of enemies)safeSpawn(e);}

function enterRoom(id,from=-1){if(!rooms[id]||rooms[id].kind==='void'||!unlockEntrance(rooms[id]))return false;current=id;remoteCommands=[];pendingInputs=[];visualPositions.clear();let r=rooms[id];W=r.width;H=r.height;combatTexts=[];player.damageFlash=0;if(partner)partner.damageFlash=0;r.visited=true;r.seen=true;for(let [n,d] of neighbors(id))if(r.edges.includes(d))rooms[n].seen=true;shots=[];bullets=[];hazards=[];enemies=[];drops=[];fx=[];boss=null;resize();player.x=W/2;player.y=H/2;if(from===0)player.y=H-48;if(from===2)player.y=48;if(from===1)player.x=48;if(from===3)player.x=W-48;if(coopActive&&partner){partner.x=Math.max(28,Math.min(W-28,player.x+30));partner.y=player.y;remoteInv=2;remoteKeys.clear();}inv=2;cool=0;doorCool=.6;clearInput();state='play';$('panel').hidden=true;if(!r.clear){if(r.kind==='battle'||r.kind==='boss')for(let p of [player,...(coopActive&&partner?[partner]:[])])if(gear(p).special.shield)p.foilReady=true;if(r.kind==='battle')spawnEnemies();else if(r.kind==='boss'){spawnBoss();}else r.clear=true}pickupDelay=.65;if(r.kind==='treasure'&&!r.used){r.used=true;spawnLoot(r,'treasure')}else if(r.kind==='shop'&&!r.used){r.used=true;spawnLoot(r,'shop')}else if(r.kind==='rest'&&!r.used){r.used=true;heal(1)}resume();hud();}
function spawnLoot(r,source){let choices=offers();r.loot=choices.map((item,i)=>({id:source+'-'+item.id,item,nx:.25+i*.25,ny:.34,price:source==='shop'?rarityPrices[item.rarity]:0,group:source==='shop'?null:'recipe',taken:false}));if(source==='shop'){r.loot.push({id:'shop-key',item:{id:'key',name:'Brass key',text:'Adds 1 shared key.',take:()=>keyCount++},nx:.78,ny:.72,price:10,taken:false});r.loot.push({id:'shop-heal',item:{id:'meal',name:'Warm snack',text:'Restore 1 life.',take:()=>heal(1)},nx:.5,ny:.72,price:12,taken:false});}pickupDelay=.8;}
function pickupItems(dt){pickupDelay=Math.max(0,pickupDelay-dt);let r=rooms[current];if(pickupDelay>0)return;for(let p of r.loot){if(p.taken)continue;let collector=livingPlayers().filter(a=>Math.hypot(a.x-p.nx*W,a.y-p.ny*H)<=24).sort((a,b)=>Math.hypot(a.x-p.nx*W,a.y-p.ny*H)-Math.hypot(b.x-p.nx*W,b.y-p.ny*H))[0];if(!collector)continue;if(!canEquip(p.item,collector)||coins<p.price||(p.maxCost&&maxLives(collector)-p.maxCost<2)||(p.item.id==='meal'&&collector.hp===maxLives(collector)))continue;coins-=p.price;if(p.maxCost){gear(collector).maxHP-=p.maxCost;collector.hp=Math.min(collector.hp,maxLives(collector))}if(p.item.id==='meal')heal(1,collector);else if(p.item.id==='key')keyCount++;else take(p.item,collector);p.taken=true;if(p.group)for(let other of r.loot)if(other.group===p.group)other.taken=true;pickupDelay=.45;burst(p.nx*W,p.ny*H,'accent');tone(880,.18);break}}
function itemExplanation(){let r=rooms[current];if(!r||state==='home'){ $('item-info').textContent='Walk over a recipe pedestal to collect it. Item effects are explained here.';return}let available=r.loot.filter(p=>!p.taken);let viewer=net.role==='guest'&&partner?partner:player;let close=available.find(p=>Math.hypot(viewer.x-p.nx*W,viewer.y-p.ny*H)<90);let describe=p=>p.item.name+(p.item.rarity?' ['+p.item.rarity.toUpperCase()+']':'')+' — '+p.item.text+(!canEquip(p.item,viewer)?' · Already equipped / at cap':'')+(p.deal?(p.maxCost?' · SPICY DEAL: costs '+p.maxCost+' maximum lives'+(maxLives(viewer)-p.maxCost<2?' (must leave you at least 2)':''):' · FLAWLESS BLESSING: free'):'')+(p.price?' · '+p.price+' coins'+(coins<p.price?' (not enough coins)':''):(p.deal?'':' · Free'));$('item-info').textContent=available.length?(close?describe(close):available.map(describe).join(' | ')):(r.kind==='rest'?'Cafe meal: restores 1 life on your first visit.':r.portal?(floor>=12?'Step onto the blue hatch to finish the campaign.':'Step onto the blue hatch to enter kitchen '+(floor+1)+'. Deals are optional.'):'Walk near a chest after clearing the room. '+(floor>=2?'Chests and locked item rooms cost 1 key.':'Floor 1 chests and item rooms are free.')+' Cover blocks shots, not marked ground attacks.');}
function roomCleared(){let r=rooms[current];if(r.clear||state!=='play')return;r.clear=true;bullets=[];hazards=[];coins+=3;score+=200;for(let p of livingPlayers())if(p.characterId==='rook'&&r.kind==='boss')p.hp=Math.min(maxLives(p),p.hp+1);if(coopActive){if(player.hp<=0)player.hp=Math.min(1,maxLives(player));if(partner&&partner.hp<=0)partner.hp=Math.min(1,maxLives(partner));inv=2;remoteInv=2}if(r.kind==='boss'){let milestone=milestones.find(m=>m.type===r.bossKind);if(milestone){if(!runMilestones.includes(milestone.id))runMilestones.push(milestone.id);recordMark(player.characterId,milestone.id);}coins+=8;score+=800;r.portal=true;bossRewards(r);if(r.champion){coins+=4}doorCool=1;pickupDelay=1}hud()}
function descend(){if(floor>=12){finish(true);return}floor++;generateFloor();enterRoom(startRoom)}
function finish(won){if(runFinished)return;runFinished=true;state='over';hideMenu();panel(won?'Shift complete!':'Run ended',`${Math.floor(score)} points. ${won?'All 12 floors delivered. ':''}Boss completion marks stay saved. Coins, keys, and recipes reset next run. No permanent stat upgrades.`);$('choices').append(button('Main menu',endFromMenu,'back-home'));hud();}
function damagePlayer(){if(inv>0||player.hp<=0||state!=='play')return;if(player.foilReady){player.foilReady=false;inv=.5;burst(player.x,player.y,'accent');return}if(rooms[current]&&rooms[current].kind==='boss'&&!rooms[current].clear)rooms[current].bossDamage++;player.hp--;damageFeedback(player,1,true);inv=1.8;burst(player.x,player.y,'accent');tone(95,.16,'sawtooth');if(player.hp<=0&&(!coopActive||!partner||partner.hp<=0))finish(false);hud()}
function pause(){if(net.role==='guest'){clearInput();net.send({type:'pause-request',paused:state==='play'});return}if(state==='play'){state='paused';clearInput();remoteKeys.clear();$('panel').hidden=true;if(master)master.gain.value=0;$('pause').disabled=false;$('pause').textContent='Resume';showMenu('session','session');}else if(state==='paused')resume();}
$('pause').onclick=pause;$('ability-button').onclick=requestAbility;
function resize(){let w=canvas.clientWidth,h=canvas.clientHeight;if(w<1||h<1)return;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d*w/VIEW_W,0,0,d*h/VIEW_H,0,0)}
if(typeof ResizeObserver==='function')new ResizeObserver(resize).observe(canvas);else window.addEventListener('resize',resize);
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(!$('menu-screen').hidden){if(menuView==='characters'&&['arrowleft','arrowright'].includes(k)){e.preventDefault();cycleCourier(k==='arrowright'?1:-1);return}if((k==='escape'||(k==='p'&&menuContext==='session'))&&!e.repeat){e.preventDefault();menuBack()}return}if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target?.tagName))return;if((k==='e'||k===' ')&&state==='play'){e.preventDefault();if(!e.repeat)requestAbility();return;}if(!['w','a','s','d','arrowup','arrowright','arrowdown','arrowleft','p','escape'].includes(k))return;if(state!=='play'&&state!=='paused')return;e.preventDefault();if(k==='p'||k==='escape'){if(!e.repeat)pause();return}keys.add(k);let n=['arrowup','arrowright','arrowdown','arrowleft'].indexOf(k);if(n>=0)lastAim=n});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{clearInput();if(state==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')pause()});
for(let group of ['move','shoot'])for(let d=0;d<4;d++){let el=$(group+'-'+d),set=group==='move'?touchMove:touchFire;el.addEventListener('pointerdown',e=>{e.preventDefault();if(state!=='play')return;el.setPointerCapture(e.pointerId);set.add(d);if(group==='shoot')lastAim=d;unlock()});for(let event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>set.delete(d));el.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&state==='play'){e.preventDefault();set.add(d);lastAim=d}});el.addEventListener('keyup',()=>set.delete(d));el.addEventListener('blur',()=>set.delete(d))}
function burst(x,y,color='gold'){for(let i=0;i<8;i++){let a=Math.random()*Math.PI*2;fx.push({x,y,vx:Math.cos(a)*70,vy:Math.sin(a)*70,life:.35,color})}}
