function updateCamera(){let p=net.role==='guest'&&partner?partner:player;if(p.hp<=0)p=livingPlayers()[0]||p;camera.x=Math.max(0,Math.min(W-VIEW_W,p.x-VIEW_W/2));camera.y=Math.max(0,Math.min(H-VIEW_H,p.y-VIEW_H/2));}
function directionTargets(){let r=rooms[current],targets=[];if(!r)return targets;for(let d of r.edges){let other=rooms[current+DX[d]+DY[d]*gridSize];targets.push({x:d===1?W-10:d===3?10:W/2,y:d===0?10:d===2?H-10:H/2,label:other?.locked?'Key door':r.clear?'Exit':'Door',color:r.clear?'accent':'danger'});}let teammate=net.role==='guest'?player:partner;if(coopActive&&teammate)targets.push({...teammate,label:teammate.hp>0?'Partner':'Downed partner',color:'gold'});for(let h of hazards)targets.push({x:h.x,y:h.kind==='beam'?camera.y+VIEW_H/2:h.y,label:h.warn>0?'! '+h.warn.toFixed(1):'DANGER',color:'danger'});if(r.clear){for(let chest of r.chests)if(!chest.opened)targets.push({...chest,label:'Chest',color:'gold'});for(let p of r.pickups)if(p.kind==='key')targets.push({...p,label:'Key',color:'gold'});}if(r.portal)targets.push({x:W*.5,y:H*.7,label:floor>=12?'End shift':'Next floor',color:'accent'});return targets;}
function drawDirections(c){if(state==='home'||!rooms[current]||(W<=VIEW_W&&H<=VIEW_H))return;for(let t of directionTargets()){let x=t.x-camera.x,y=t.y-camera.y;if(x>=16&&x<=VIEW_W-16&&y>=16&&y<=VIEW_H-16)continue;let dx=x-VIEW_W/2,dy=y-VIEW_H/2,scale=Math.min((VIEW_W/2-48)/Math.max(1,Math.abs(dx)),(VIEW_H/2-28)/Math.max(1,Math.abs(dy)));x=VIEW_W/2+dx*scale;y=VIEW_H/2+dy*scale;ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(dy,dx));ctx.fillStyle=c(t.color);ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(-5,-5);ctx.lineTo(-5,5);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle=c(t.color);ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(t.label,x,y+16);}}
